#!/usr/bin/env bash
# Copy the web app into mobile/www for Capacitor.
# www/ is gitignored and regenerated by this script, so the ~130 MB of
# vendored mushaf images are not duplicated in git.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/.." && pwd)"
WWW="$HERE/www"

rm -rf "$WWW"
mkdir -p "$WWW"
cp "$ROOT/index.html" "$ROOT/offline.html" "$ROOT/manifest.json" "$ROOT/sw.js" "$WWW/"
cp -r "$ROOT/pages" "$ROOT/assets" "$ROOT/data" "$WWW/"
echo "synced web app -> $WWW ($(du -sh "$WWW" | cut -f1))"
